/* Toolbox 2.3.6 — offline Sea Service + Maritime CV workspace. No identity numbers. */
(()=>{'use strict';
const KEY='toolbox2-career-v1';
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=()=>{try{const d=JSON.parse(localStorage.getItem(KEY)||'{}');return {profile:d.profile||{},voyages:Array.isArray(d.voyages)?d.voyages:[],template:d.template==='ready'?'ready':'clean'}}catch{return {profile:{},voyages:[],template:'clean'}}};
const put=d=>{try{localStorage.setItem(KEY,JSON.stringify(d));return true}catch{alert('Storage is unavailable. Export your records and check browser storage.');return false}};
const days=(a,b)=>{if(!a||!b)return null;const n=Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/86400000)+1;return Number.isFinite(n)&&n>0?n:null};
const duration=n=>n===null?'Dates incomplete':`${n} day${n===1?'':'s'}`;
const field=(name,label,type='text',value='',required=false)=>`<label class="field">${label}<input name="${name}" type="${type}" value="${safe(value)}" ${required?'required':''} maxlength="120" autocomplete="off"></label>`;
const intro=(heading,sub)=>`<button type="button" class="back" data-open="documents">← Documents</button><div class="career-hero"><span>TOOLBOX · MARITIME CAREER</span><h1>${heading}</h1><p>${sub}</p></div>`;
function sea(){const d=get(),list=d.voyages.slice().sort((a,b)=>(b.signon||'').localeCompare(a.signon||''));const total=list.reduce((n,x)=>n+(days(x.signon,x.signoff)||0),0);return intro('Sea Service','Maintain a record of your vessels, ranks and service dates.')+`<div class="career-summary"><strong>${list.length}</strong><span>Recorded voyages</span><strong>${total}</strong><span>Completed service days</span></div><button type="button" class="btn full" data-career="add-voyage">+ Add Sea Service</button><div class="career-list">${list.length?list.map(x=>`<article class="career-entry"><div><strong>${safe(x.vessel)}</strong><small>${safe(x.rank||'Rank not entered')} · ${safe(x.vesselType||'Vessel type not entered')}</small><small>${safe(x.signon||'Start unknown')} → ${safe(x.signoff||'Ongoing / not entered')}</small><small>${duration(days(x.signon,x.signoff))}</small></div><button type="button" class="btn secondary" data-career-edit="${safe(x.id)}">Edit</button></article>`).join(''):'<div class="card"><p>No sea service records yet. Add your first vessel to start your maritime history.</p></div>'}</div><button type="button" class="btn secondary full" data-career="export">Export Sea Service Backup (JSON)</button><button type="button" class="btn secondary full" data-career="import">Restore Career Backup (JSON)</button><p class="career-notice">Records are saved only in this browser on this preview URL. This is a personal log, not an official sea service certificate.</p>`}
function cv(){const d=get(),p=d.profile;return intro('Maritime CV','Build a clean, printable seafarer CV from your profile and Sea Service records.')+`<div class="card career-form"><h2>Professional details</h2><p class="muted">Do not enter passport numbers, medical details, or other sensitive identifiers.</p><form id="careerProfileForm">${field('name','Name', 'text',p.name||'',true)}${field('rank','Target rank / position','text',p.rank||'')}${field('department','Department','text',p.department||'')}${field('email','Contact email','email',p.email||'')}${field('phone','Contact number','tel',p.phone||'')}${field('summary','Professional summary','text',p.summary||'')}${field('certificates','Certificates / STCW training (separate with commas)','text',p.certificates||'')}${field('skills','Key maritime skills (separate with commas)','text',p.skills||'')}<button class="btn full" type="submit">Save CV Details</button></form></div><div class="card career-templates"><h2>Choose CV layout</h2><p class="muted">Both layouts use the same saved information. Change your choice any time.</p><div class="career-template-grid"><button type="button" class="career-template ${d.template==='clean'?'selected':''}" data-cv-template="clean" aria-pressed="${d.template==='clean'}"><span class="career-template-mini clean"><i></i><i></i><i></i><i></i></span><strong>Clean CV</strong><small>Simple professional layout</small></button><button type="button" class="career-template ${d.template==='ready'?'selected':''}" data-cv-template="ready" aria-pressed="${d.template==='ready'}"><span class="career-template-mini ready"><i></i><i></i><i></i><i></i></span><strong>Ready-made Maritime</strong><small>Structured maritime resume</small></button></div></div><div class="card"><h2>Sea Service</h2><p>${d.voyages.length} record(s) will appear on your CV.</p><button type="button" class="btn secondary full" data-career="go-sea">Manage Sea Service</button></div><button type="button" class="btn full" data-career="preview-cv">Preview / Print CV</button><button type="button" class="btn secondary full" data-career="export">Export Career Backup (JSON)</button><button type="button" class="btn secondary full" data-career="import">Restore Career Backup (JSON)</button><p class="career-notice">Your CV is a draft for review. Verify all entries before sending it to an employer.</p>`}
const original=documentSpecialPage;
documentSpecialPage=function(id){if(id==='sea-service')return sea();if(id==='cv')return cv();return original(id)};
function modal(html){openModal(html)};
function voyageEditor(id){const d=get(),x=d.voyages.find(v=>v.id===id)||{};modal(`<h2>${id?'Edit':'Add'} Sea Service</h2><form id="careerVoyageForm" data-id="${safe(id||'')}">${field('vessel','Vessel name','text',x.vessel||'',true)}${field('imo','IMO number (optional)','text',x.imo||'')}${field('vesselType','Vessel type (e.g. LNG Carrier)','text',x.vesselType||'')}${field('rank','Rank / capacity','text',x.rank||'')}${field('company','Company (optional)','text',x.company||'')}${field('signon','Sign-on date','date',x.signon||'')}${field('signoff','Sign-off date (leave blank if onboard)','date',x.signoff||'')}<p class="muted" id="careerError" role="alert"></p><button type="submit" class="btn full">Save Sea Service</button>${id?'<button type="button" class="btn secondary full" data-career="delete-voyage">Delete this record</button>':''}</form>`)}
function printCV(){const d=get(),p=d.profile;if(!p.name?.trim()){alert('Please save your name in CV details first.');return}const rows=d.voyages.slice().sort((a,b)=>(b.signon||'').localeCompare(a.signon||''));const ready=d.template==='ready';const html=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Maritime CV</title><style>body{font:14px/1.5 system-ui,Arial;color:#18342d;margin:0;padding:28px}h1{font-size:28px;margin:0}body.ready{color:#172b35;font-family:Arial,sans-serif}body.ready .cv-head{background:#0d5143;color:white;padding:22px 24px;margin:-28px -28px 24px}body.ready .cv-head .sub{color:#d5f1e7}body.ready h2{border-color:#0d5143;text-transform:uppercase;letter-spacing:.08em;font-size:15px}body.ready table th{background:#e9f4ef;color:#0d5143}body.ready .cv-contact{font-size:12px} .cv-head{page-break-inside:avoid}h2{border-bottom:2px solid #145b48;padding-bottom:7px;margin-top:28px}small{color:#576e66}.sub{color:#45645a}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:8px 6px;border-bottom:1px solid #d8e4de}button{padding:12px 20px;background:#145b48;color:white;border:0;border-radius:8px}@media print{button{display:none}body{padding:0}body.ready .cv-head{margin:-16mm -16mm 24px;padding:18mm 16mm 10mm;-webkit-print-color-adjust:exact;print-color-adjust:exact}@page{size:A4;margin:16mm}}</style></head><body class="${ready?'ready':'clean'}"><button onclick="window.print()">Print / Save as PDF</button><header class="cv-head"><h1>${safe(p.name)}</h1><div class="sub">${safe(p.rank||'')} ${p.department?'· '+safe(p.department):''}</div><div class="cv-contact">${safe(p.email||'')} ${p.phone?'· '+safe(p.phone):''}</div></header>${p.summary?`<h2>Profile</h2><p>${safe(p.summary)}</p>`:''}${p.certificates?`<h2>Certificates & Training</h2><p>${safe(p.certificates)}</p>`:''}${p.skills?`<h2>Maritime Skills</h2><p>${safe(p.skills)}</p>`:''}<h2>Sea Service</h2>${rows.length?`<table><thead><tr><th>Vessel</th><th>Type</th><th>Rank</th><th>Sign on</th><th>Sign off</th><th>Days</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${safe(x.vessel)}</td><td>${safe(x.vesselType||'')}</td><td>${safe(x.rank||'')}</td><td>${safe(x.signon||'')}</td><td>${safe(x.signoff||'Onboard')}</td><td>${days(x.signon,x.signoff)??'—'}</td></tr>`).join('')}</tbody></table>`:'<p>No sea service records entered.</p>'}<p><small>Prepared using Toolbox. Verify all details before submitting. Not an official certificate.</small></p></body></html>`;const w=window.open('','_blank');if(!w){alert('Allow pop-ups to preview the CV, or try opening Toolbox in your browser.');return}w.document.open();w.document.write(html);w.document.close()}
document.addEventListener('click',e=>{const template=e.target.closest('[data-cv-template]');if(template){const d=get();d.template=template.dataset.cvTemplate==='ready'?'ready':'clean';if(put(d))render();return}const edit=e.target.closest('[data-career-edit]');if(edit){voyageEditor(edit.dataset.careerEdit);return}const b=e.target.closest('[data-career]');if(!b)return;switch(b.dataset.career){case 'add-voyage':voyageEditor();break;case 'delete-voyage':{const form=document.getElementById('careerVoyageForm');if(!form||!confirm('Delete this sea service entry?'))return;const d=get();d.voyages=d.voyages.filter(v=>v.id!==form.dataset.id);if(put(d)){closeModal();render()}break}case 'go-sea':navigate('doc-sea-service');break;case 'preview-cv':printCV();break;case 'import':{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;if(file.size>1024*1024){alert('Backup is too large. Select a Toolbox Career JSON backup under 1 MB.');return}try{const data=JSON.parse(await file.text());if(data.format!=='toolbox2-career-v1'||!Array.isArray(data.voyages)||!data.profile||typeof data.profile!=='object'||Array.isArray(data.profile)||data.voyages.length>1000||data.voyages.some(v=>!v||typeof v!=='object'||typeof v.vessel!=='string'||typeof v.id!=='string'))throw Error('Invalid backup');const current=get();const count=data.voyages.length;if(!confirm(`Restore ${count} Sea Service records and CV details? This replaces your current Career Workspace records. Export a backup first if needed.`))return;const clean={profile:{},voyages:[],template:data.template==='ready'?'ready':'clean'};for(const k of ['name','rank','department','email','phone','summary','certificates','skills'])clean.profile[k]=String(data.profile[k]??'').slice(0,120);for(const v of data.voyages){const out={};for(const k of ['id','vessel','imo','vesselType','rank','company','signon','signoff'])out[k]=String(v[k]??'').slice(0,120);clean.voyages.push(out)}if(put(clean)){alert('Career backup restored successfully.');render()}}catch{alert('Could not restore this file. Choose a valid Toolbox Career JSON backup.')}});input.click();break}case 'export':{const blob=new Blob([JSON.stringify({format:'toolbox2-career-v1',exportedAt:new Date().toISOString(),...get()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='toolbox-career-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);break}}});
document.addEventListener('submit',e=>{if(e.target.id==='careerVoyageForm'){e.preventDefault();const f=e.target,fd=new FormData(f),x=Object.fromEntries(fd.entries());x.vessel=x.vessel.trim();if(!x.vessel){document.getElementById('careerError').textContent='Enter a vessel name.';return}if(x.signon&&x.signoff&&x.signoff<x.signon){document.getElementById('careerError').textContent='Sign-off must not be earlier than sign-on.';return}const d=get(),id=f.dataset.id||'sea-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);x.id=id;const idx=d.voyages.findIndex(v=>v.id===id);if(idx>=0)d.voyages[idx]=x;else d.voyages.push(x);const btn=f.querySelector('[type=submit]');btn.disabled=true;if(put(d)){closeModal();render()}else btn.disabled=false;}if(e.target.id==='careerProfileForm'){e.preventDefault();const f=e.target,d=get();d.profile=Object.fromEntries(new FormData(f).entries());const btn=f.querySelector('[type=submit]');btn.disabled=true;if(put(d)){render()}else btn.disabled=false;}});
})();
